var n=`0015-kruchenyky`;var o=`world-0015`;var i=`UA`;var s=`eastern-europe`;var l=4;var r=62;var a={en:`Kruchenyky`,ua:`Крученики`};var u={en:`A classic dish from Ukraine, featuring button mushroom, yellow onion, pork loin, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: печериця, жовта цибуля, свиняча корейка, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`button-mushroom`,230,`g`],[`yellow-onion`,120,`g`],[`unsalted-butter`,25,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Pound the pork loin into four thin cutlets; brush lightly with mustard and season.`,ua:`Відбийте свинячу корейку на чотири тонкі пласти, змастіть гірчицею та приправте.`,t:[`marinating`],m:10,i:[[`pork-loin`,600,`g`],[`dijon-mustard`,20,`g`]]},{en:`Spoon the cooled mushroom-onion filling onto each cutlet, roll tightly and secure with kitchen twine or toothpicks.`,ua:`Викладіть охолоджену грибно-цибулеву начинку, щільно скрутіть рулетики та закріпіть ниткою або шпажками.`,t:[`rolling-stuffed-food`],m:10,i:[]},{en:`Brown the rolls first, then roast at 190°C until pork is safely cooked (at least 63°C followed by a 3-minute rest).`,ua:`Спочатку підрум’яньте рулетики, тоді запікайте при 190°C до безпечної готовності свинини (не нижче 63°C із подальшим відпочинком 3 хвилини).`,t:[`roasting`],m:30,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,12,`g`]]}];var g={slug:n,id:o,country:`UA`,region:s,servings:4,minutes:62,title:a,text:u,steps:h};export{i as country,g as default,o as id,r as minutes,s as region,l as servings,n as slug,h as steps,u as text,a as title};